class RandomizedSet {
    private final java.util.ArrayList<Integer> values = new java.util.ArrayList<>();
    private final java.util.Map<Integer, Integer> indexes = new java.util.HashMap<>();
    private final java.util.Random random = new java.util.Random();

    public RandomizedSet() {
    }

    public boolean insert(int val) {
        if (indexes.containsKey(val)) {
            return false;
        }
        indexes.put(val, values.size());
        values.add(val);
        return true;
    }

    public boolean remove(int val) {
        Integer index = indexes.get(val);
        if (index == null) {
            return false;
        }
        int lastIndex = values.size() - 1;
        int lastValue = values.get(lastIndex);
        values.set(index, lastValue);
        indexes.put(lastValue, index);
        values.remove(lastIndex);
        indexes.remove(val);
        return true;
    }

    public int getRandom() {
        return values.get(random.nextInt(values.size()));
    }
}

class RandomizedSet {
    private int[] values = new int[4];
    private int size;
    private final java.util.Map<Integer, Integer> indexes = new java.util.HashMap<>();
    private final java.util.Random random = new java.util.Random();

    public RandomizedSet() {
    }

    public boolean insert(int val) {
        if (indexes.containsKey(val)) {
            return false;
        }
        ensureCapacity();
        values[size] = val;
        indexes.put(val, size);
        size++;
        return true;
    }

    public boolean remove(int val) {
        Integer index = indexes.get(val);
        if (index == null) {
            return false;
        }
        int lastValue = values[size - 1];
        values[index] = lastValue;
        indexes.put(lastValue, index);
        size--;
        indexes.remove(val);
        return true;
    }

    public int getRandom() {
        return values[random.nextInt(size)];
    }

    private void ensureCapacity() {
        if (size == values.length) {
            values = java.util.Arrays.copyOf(values, values.length * 2);
        }
    }
}

