class RandomizedSet {
    private static class Entry {
        int value;
        int index;

        Entry(int value, int index) {
            this.value = value;
            this.index = index;
        }
    }

    private final java.util.ArrayList<Entry> dense = new java.util.ArrayList<>();
    private final java.util.Map<Integer, Entry> entries = new java.util.HashMap<>();
    private final java.util.Random random = new java.util.Random();

    public RandomizedSet() {
    }

    public boolean insert(int val) {
        if (entries.containsKey(val)) {
            return false;
        }
        Entry entry = new Entry(val, dense.size());
        dense.add(entry);
        entries.put(val, entry);
        return true;
    }

    public boolean remove(int val) {
        Entry entry = entries.remove(val);
        if (entry == null) {
            return false;
        }
        int index = entry.index;
        Entry last = dense.remove(dense.size() - 1);
        if (entry != last) {
            dense.set(index, last);
            last.index = index;
        }
        return true;
    }

    public int getRandom() {
        return dense.get(random.nextInt(dense.size())).value;
    }
}

class RandomizedSet {
    private static final int TABLE_SIZE = 1 << 20;
    private int[] values = new int[4];
    private int size;
    private final int[] keys = new int[TABLE_SIZE];
    private final int[] indexes = new int[TABLE_SIZE];
    private final byte[] states = new byte[TABLE_SIZE];
    private final java.util.Random random = new java.util.Random();

    public RandomizedSet() {
    }

    public boolean insert(int val) {
        if (findKey(val) != -1) {
            return false;
        }
        ensureCapacity();
        int slot = findInsertSlot(val);
        keys[slot] = val;
        indexes[slot] = size;
        states[slot] = 1;
        values[size] = val;
        size++;
        return true;
    }

    public boolean remove(int val) {
        int slot = findKey(val);
        if (slot == -1) {
            return false;
        }
        int index = indexes[slot];
        int lastValue = values[size - 1];
        values[index] = lastValue;
        size--;
        states[slot] = 2;
        if (index < size) {
            int lastSlot = findKey(lastValue);
            indexes[lastSlot] = index;
        }
        return true;
    }

    public int getRandom() {
        return values[random.nextInt(size)];
    }

    private int findKey(int key) {
        int slot = hash(key);
        while (states[slot] != 0) {
            if (states[slot] == 1 && keys[slot] == key) {
                return slot;
            }
            slot = (slot + 1) & (TABLE_SIZE - 1);
        }
        return -1;
    }

    private int findInsertSlot(int key) {
        int slot = hash(key);
        int firstDeleted = -1;
        while (states[slot] != 0) {
            if (states[slot] == 2 && firstDeleted == -1) {
                firstDeleted = slot;
            }
            slot = (slot + 1) & (TABLE_SIZE - 1);
        }
        return firstDeleted == -1 ? slot : firstDeleted;
    }

    private int hash(int key) {
        int h = key ^ (key >>> 16);
        return h & (TABLE_SIZE - 1);
    }

    private void ensureCapacity() {
        if (size == values.length) {
            values = java.util.Arrays.copyOf(values, values.length * 2);
        }
    }
}
